const toRad = d => d * Math.PI / 180;

// Location 1: Device (San Francisco, CA)
const lat1 = 37.7749, lon1 = -122.4194;

// Location 2: Boston, MA 02118 (approx coords for zip 02118)
const lat2 = 42.3396, lon2 = -71.0693;

// Haversine formula
const dLat = toRad(lat2 - lat1);
const dLon = toRad(lon2 - lon1);
const a = Math.sin(dLat/2)**2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon/2)**2;
const c = 2 * Math.asin(Math.sqrt(a));

const R_km = 6371.0;
const R_mi = 3958.8;

console.log('=== Distance Calculation ===');
console.log('');
console.log('📍 From: Your device location');
console.log('   (37.7749°N, 122.4194°W) — San Francisco, CA');
console.log('');
console.log('📦 To:   Order #W4705780 shipping address');
console.log('   4829 Elm Ridge Way, Suite 7, Boston, MA 02118, USA');
console.log('   (42.3396°N, 71.0693°W) — approx. coords for ZIP 02118');
console.log('');
console.log('📏 Straight-line (great-circle) distance:');
console.log('   • ' + (R_km * c).toLocaleString('en-US', {maximumFractionDigits:1}) + ' km');
console.log('   • ' + (R_mi * c).toLocaleString('en-US', {maximumFractionDigits:1}) + ' miles');
"
